// Merge adjacent equal-color map cells; rebuild each call so fog/terrain edits are immediate.
function drawRegionMapFloor(context,map,x,y,scale){let pixel=Math.ceil(scale);for(let row=0;row<MH;row++){let start=-1,tone=0;for(let col=0;col<=MW;col++){let i=row*MW+col,current=col<MW&&map.seen[i]&&map.tiles[i]?(map.visible[i]?2:1):0;if(current===tone)continue;if(tone){context.fillStyle=tone===2?'#93a58a':'#43594d';context.fillRect(x+start*scale,y+row*scale,(col-start-1)*scale+pixel,pixel);}start=col;tone=current;}}}
function regionFloorDiamond(context,s){context.beginPath();context.moveTo(s.x,s.y-TILE*ISOY);context.lineTo(s.x+TILE*ISOX,s.y);context.lineTo(s.x,s.y+TILE*ISOY);context.lineTo(s.x-TILE*ISOX,s.y);context.closePath();}
function paintRegionFloor(context,gx,gy,s){let noise=((gx*73+gy*37)%17)/17,r=REGIONS[worldRegion];context.save();regionFloorDiamond(context,s);context.fillStyle=villageOpen?'#63705a':r.color;context.fill();context.fillStyle='rgba(0,0,0,'+(noise*.15)+')';context.fill();if((gx*11+gy*7)%9===0){context.strokeStyle=villageOpen?'#d3bf8b66':'#dce5c533';context.lineWidth=1;context.beginPath();context.moveTo(s.x-7,s.y+3);context.lineTo(s.x-4,s.y-6);context.lineTo(s.x,s.y+3);context.lineTo(s.x+4,s.y-3);context.stroke()}if(villageOpen&&(Math.abs(gx-9)<=1||Math.abs(gy-9)<=1)){regionFloorDiamond(context,s);context.fillStyle='#b7a68955';context.fill()}if(!dungeon.visible[cell(gx,gy)]){regionFloorDiamond(context,s);context.fillStyle='#000a';context.fill()}context.restore()}
const regionFloorBase=floorTile;floorTile=(gx,gy)=>{if(!p?.campaign)return regionFloorBase(gx,gy);if(!isFloor(gx,gy))return;let pos=center(gx,gy),s=project(pos.x,pos.y);if(s.x<-100||s.y<-100||s.x>W+100||s.y>H+100)return;paintRegionFloor(ctx,gx,gy,s);};
