 for(let marker of questMapMarkers()){let mx=x+marker.x*scale,my=y+marker.y*scale,r=large?7:4;ctx.fillStyle=marker.kind==='return'?'#a4efba':'#8ce6ed';ctx.strokeStyle='#102b35';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(mx,my-r);ctx.lineTo(mx+r,my);ctx.lineTo(mx,my+r);ctx.lineTo(mx-r,my);ctx.closePath();ctx.fill();ctx.stroke();if(large&&marker.kind==='return'){ctx.font='bold 11px sans-serif';ctx.textAlign='center';ctx.fillStyle='#a4efba';ctx.fillText('村へ帰還',mx,my-12);}}
